import json,random,re,itertools
from pathlib import Path
root=Path(__file__).resolve().parents[2]/'content/launch-art'
if (root/'production-briefs.json').exists():
    queue=json.loads((root/'production-briefs.json').read_text())
    plan=json.loads((root/'plan.json').read_text())
    entries=queue['entries']
    if len(entries)!=2500 or len({e['compositionId'] for e in entries})!=2500:
        raise SystemExit('Existing production queue is incomplete or has duplicate identities; repair it without rerolling.')
    if queue.get('geometryHash')!=plan['geometryHash']:
        raise SystemExit('Production queue geometry does not match the frozen plan.')
    print('Reusing 2500 frozen composition briefs; existing identities, art revisions and palettes are preserved.')
    raise SystemExit(0)
