metamorphoses=[('river_pour','river pour','a broad river pours from the object and becomes a little leaf bridge'),('island_unfold','unfolding island','the object unfolds into a broad island with one huge leaf palm'),('flower_machine','flower machine','one enormous flower grows through the object and turns one broad gear'),('stairs_spill','spilling staircase','five oversized steps spill out of the object into a broad leaf pond'),('paper_flight','paper flight','three broad folded wings lift a little garden platform from the object'),('lamp_garden','lamp garden','a huge glowing flower opens inside the object above two broad leaves'),('cloud_portal','cloud portal','one huge cloud passes through the object and becomes a leaf-shaped boat'),('seed_symphony','seed symphony','three enormous seeds roll through the object like a tiny musical machine'),('rainbow_wheel','rainbow wheel','a huge petal wheel turns around the object above a broad green base'),('water_swing','water swing','one enormous leafy swing hangs inside the object above a broad water bowl'),('moon_blossom','celestial blossom','one huge glowing blossom opens through the object with two broad curled leaves'),('tidal_bridge','tidal bridge','one huge leaf bridge rises from the object as a tiny ferry passes')]

pools=[]
def pool(category,left,right,kind):
 out=[]
 for noun in left:
  for key,label,cue in right:
   concept=slug(noun)+':'+key
   cid=slug(noun+' '+key)
   title=noun.title()+' '+label.title()
   if kind=='house':brief=f'An enormous {noun} has become a cozy {label}. Preserve the unmistakable {noun} silhouette; {cue}. One big main form, one story cue, sparse surroundings.'
   elif kind=='machine':brief=f'A giant {noun} operates as a whimsical {label}: {cue}. Preserve the recognizable {noun} main form and one very large mechanical cue.'
   elif kind=='vehicle':brief=f'A huge {noun} transformed into a garden {label}, with {cue}. The original {noun} shape is unmistakable, complete side-view vehicle, sparse setting.'
   elif kind=='job':brief=f'A friendly large {noun} works as a {label}, using {cue}. The animal and ONE oversized profession prop fill the panel; expressive whole-body pose, no clothing-only gag.'
   elif kind=='world':brief=f'An enormous open {noun} contains a miniature {label}: {cue}. One large enclosing silhouette and one clear inner landscape, no tiny clutter.'
   elif kind=='cosmic':brief=f'A huge {noun} holds a magical {label}: {cue}. Broad celestial silhouette, one large garden mechanism, no tiny stars or writing.'
   else:brief=f'An unmistakable huge {noun} in a surreal garden transformation: {cue}. Keep the whole main silhouette and one clear secondary function.'
   out.append({'compositionId':cid,'conceptKey':concept,'title':title,'displayName':title,'artBrief':brief,'direction':category})
 rng.shuffle(out);pools.append(out)
pool('impossible_homes',containers,functions,'house')
pool('natural_mechanisms',containers,mechanisms,'machine')
pool('unusual_travel',containers,vehicles,'vehicle')
pool('little_professions',animals,jobs,'job')
pool('pocket_worlds',containers,worlds,'world')
pool('celestial_gardens',cosmic,cosmic_functions,'cosmic')
pool('surreal_still_life',containers,metamorphoses,'meta')
# Avoid reauthoring the already selected full concepts, regardless of a differently worded title.
reserved_pairs=set(words('boot:greenhouse|moon:windmill|jellyfish:airship|lilypad:bakery|teacup:leaf_steam|leaf:sailing_ferry|teapot:submarine|turtle:greenhouse|camera:greenhouse|cactus:train_station|seashell:carousel|umbrella:greenhouse|whale:post_office|book:library|walnut:cable_car|rose:pottery_kiln|pocket_watch:floating_island|accordion:river_pour|gramophone:river_pour|lantern:flower_market|mushroom:drawbridge|crocodile:orchard|teacup:stairs_spill|hedgehog:post_office'))
used_ids={e['compositionId'] for e in book['compositions']};used_concepts=set(reserved_pairs)
manual={}
for f in sorted((root/'batches').glob('atlas-000[2345].json')):
 b=json.loads(f.read_text())
 for e in b['entries']:manual[e['level']]={**e,'direction':'authored_first100','paletteRoles':b['paletteRoles']}
used_ids.update(e['compositionId'] for e in manual.values())
# Concrete icons have a clear primary object and one broad botanical support, rather than reused story templates.
simple=[]
for obj in objects:
 cid=slug(obj)
 if cid in used_ids:continue
 simple.append({'compositionId':cid,'conceptKey':'icon:'+cid,'title':obj.title(),'displayName':obj.title(),
  'artBrief':f'One unmistakable chunky {obj}, fully visible, with one broad leaf-shaped base or leaf attachment as the only garden cue. Use large color masses and keep the primary object immediately recognizable.', 'direction':'recognizable_objects'})
queue=[];simple_index=0;story_index=0
for slot in plan['slots']:
 n=slot['level']
 if n in existing:
  e=existing[n];queue.append({'level':n,'compositionId':e['compositionId'],'title':e['title'],'state':'registered'});continue
 if n in manual:
  item=dict(manual[n])
 else:
  if slot['artKind']=='simple':
   while simple_index<len(simple) and simple[simple_index]['compositionId'] in used_ids:simple_index+=1
   if simple_index>=len(simple):raise ValueError('Not enough distinct concrete object briefs')
   item=dict(simple[simple_index]);simple_index+=1
  else:
   while True:
    group=story_index%len(pools);story_index+=1
    if not pools[group]:continue
    item=pools[group].pop()
    if item['compositionId'] not in used_ids and item['conceptKey']not in used_concepts:break
  item['level']=n
  target=4 if n<45 or(n>=501 and slot['artKind']=='simple') else 6 if n>=300 and slot['artKind']=='story' else 5
  item['paletteRoles']=min(slot['variantCount'][1],max(slot['variantCount'][0],target))
  if n in (200,201):item['red']=True
 used_ids.add(item['compositionId']);used_concepts.add(item.get('conceptKey',item['compositionId']))
 item.update({'width':slot['width'],'height':slot['height'],'artKind':slot['artKind'],'state':'pending'})
 queue.append(item)
assert len(queue)==2500 and len({e['compositionId'] for e in queue})==2500
(root/'production-briefs.json').write_text(json.dumps({'schemaVersion':1,'target':2500,'note':'Authoring briefs are not finished or approved artwork; status is tracked by actual registry/library checks.','entries':queue},ensure_ascii=False,indent=2)+'\n')
# Keep the three hand-directed next atlases. The remainder is partitioned by actual progression color budget.
remaining=[e for e in queue if e['state']=='pending' and e['level']not in manual]
number=6
for colors,red in [(4,False),(5,False),(6,False),(5,True)]:
 entries=[e for e in remaining if e['paletteRoles']==colors and e.get('red',False)==red]
 for start in range(0,len(entries),20):
  selected=entries[start:start+20];count=len(selected);cols=4 if count>4 else count;rows=(count+cols-1)//cols
  # Last sheets may have one empty slot, explicitly marked as unused in the prompt.
  name=f'atlas-{number:04d}';number+=1
  b={'schemaVersion':1,'referenceFile':f'content/launch-art/references/{name}.png','columns':cols,'rows':rows,'paletteRoles':colors,'entries':selected}
  (root/'batches'/f'{name}.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n')
  palette='cyan background, fresh green, warm orange, candy '+('red' if red else 'pink')
  if colors>=5:palette+=', bright lemon yellow'
  if colors>=6:palette+=', deep forest green'
  style=f'Production atlas of {count} DIFFERENT ORIGINAL pixel mosaic illustrations for a cozy garden puzzle. EXACTLY {cols} COLUMNS and {rows} ROWS, equal rectangular panels with wide straight ivory gutters. '+('Portrait image. 'if rows>cols else'Square or landscape image. ')+f'Each panel has flat pale CYAN background. Crisp chunky grid-aligned square pixel art, no text, labels, numbers, gradients or tiny texture. Use ONLY {colors} flat colors inside panels: {palette}. All colors must have broad meaningful areas, no one-pixel accents; no white or black inside panels. Main subject fully visible and filling 80 percent of panel width and height. Stories read as one main silhouette and ONE unusually clear function; no small crowds. Every complete composition is different, no recolored or resized versions. Row-major subjects: '
  prompt=style+' '.join(f'{i+1}. {e["artBrief"]}' for i,e in enumerate(selected))
  if rows*cols>count:prompt+=' Remaining final panel cells are blank cyan with no illustration.'
  (root/'batches'/f'{name}.prompt.txt').write_text(prompt+'\n')
print('briefs:',len(queue),'already registered:',len(existing),'pending:',len(queue)-len(existing),'concrete objects available:',len(objects),'simple used:',simple_index,'total atlases:',number-1)
